contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address from,
        address caddress,
        address[] memory _tos,
        uint[] memory v
    ) public payable {
        // The rule only concerns successful completion versus revert.
        // We drive c.transfer only when the argument-length precondition
        // (required by c.transfer itself) is satisfiable.
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool reverted;
        bool returned;
        try c.transfer(from, caddress, _tos, v) returns (bool _r) {
            returned = _r;
            reverted = false;
        } catch {
            reverted = true;
            returned = false;
        }

        // General rule: if the call completes successfully, it returns true.
        // If it reverts, no return value is observed.
        assert(reverted || returned == true);
    }

    receive() external payable {}
}

