contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address from, address target, address[] memory tos, uint[] memory vals) public {
        require(tos.length == vals.length, "lengths must match");
        require(tos.length > 0, "need at least one recipient");

        bool reverted;
        try c.transfer(from, target, tos, vals) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool callSucceeds;
        if (target.code.length == 0) {
            callSucceeds = true;
        } else {
            (bool success, ) = target.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, tos[0], vals[0]));
            callSucceeds = success;
        }

        assert(!reverted == callSucceeds);
    }
}

